INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Werkzeuge wie Software immer notwendig für die Strukturierung eines Unternehmens?', 2, '[{"text": "Nein", "correct": true, "because": "Auch manuelle Methoden funktionieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich Ressourcen zur Organisation einsetze?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Optimiert Arbeitsabläufe"}, {"text": "Maximale Komplexität", "correct": false, "because": "Gegenteil von Organisation"}, {"text": "Manuelle Dokumentation", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge unterstützen typischerweise die Unternehmensstruktur?', 5, '[{"text": "Projektmanagement-Software", "correct": true, "because": "Koordiniert Aufgaben"}, {"text": "ERP-Systeme", "correct": true, "because": "Integrieren Prozesse"}, {"text": "Grafikdesign-Tools", "correct": false, "because": "Nicht prozessbezogen"}, {"text": "Spieleplattformen", "correct": false, "because": "Kein Organisationszweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Organisationsmittel fördern Kommunikation. b) Sie ersetzen Mitarbeiter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht ihre Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl von Werkzeugen für die Strukturierung?', 4, '[{"text": "Benutzerfreundlichkeit", "correct": false, "because": "Fördert Akzeptanz"}, {"text": "Integration", "correct": false, "because": "Wichtig für Prozesse"}, {"text": "Farbanpassung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Werkzeuge immer cloudbasiert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal installierbar"}, {"text": "Ja", "correct": false, "because": "Cloud ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend für die Wahl eines Planungstools?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Passt sich Prozessen an"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht relevant"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Zu zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten moderne Organisationsmittel?', 5, '[{"text": "Automatisierung", "correct": true, "because": "Reduziert manuelle Arbeit"}, {"text": "Transparenz", "correct": true, "because": "Klärt Verantwortlichkeiten"}, {"text": "Hohe Rechenleistung", "correct": false, "because": "Nicht primär"}, {"text": "Spieleunterstützung", "correct": false, "because": "Kein Organisationsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Werkzeuge verbessern die Zusammenarbeit. b) Sie sind immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz von Organisationsmitteln?', 4, '[{"text": "Schulungen", "correct": false, "because": "Fördern effektive Nutzung"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "3D-Modellierung", "correct": true, "because": "Kein Organisationsbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Werkzeuge nur für große Unternehmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMUs nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben unterstützen solche Ressourcen effektiv?', 4, '[{"text": "Aufgabenplanung", "correct": true, "because": "Koordiniert Projekte"}, {"text": "Ressourcenzuweisung", "correct": true, "because": "Optimiert Einsatz"}, {"text": "Bildbearbeitung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Werkzeuge immer komplex sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können benutzerfreundlich sein"}, {"text": "Ja", "correct": false, "because": "Komplexität variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Tools für Prozesse?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Wachstum an"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Organisationsmittel sparen Zeit. b) Sie ersetzen Führungskräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht ihre Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen ein gutes Organisationstool aus?', 5, '[{"text": "Integration mit Systemen", "correct": true, "because": "Fördert reibungslose Abläufe"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Erleichtert Adoption"}, {"text": "Hohe Auflösung", "correct": false, "because": "Nicht relevant"}, {"text": "Gaming-Funktionen", "correct": false, "because": "Kein Organisationszweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung solcher Werkzeuge unwichtig?', 3, '[{"text": "Datensicherheit", "correct": false, "because": "Schützt sensible Daten"}, {"text": "Support", "correct": false, "because": "Hilft bei Problemen"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Organisationsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern solche Werkzeuge immer Internet?', 3, '[{"text": "Nein", "correct": true, "because": "Offline-Tools existieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig online"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Werkzeuge für Einzelpersonen nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Auch für persönliche Planung"}, {"text": "Nein", "correct": false, "because": "Vielseitig einsetzbar"}]'),
